fund-js/09-maps-sets-and-json/01-lru-cac.solution:
export function createLru(capacity) {
  const map = new Map();
  const touch = (key, value) => {
    map.delete(key);
    map.set(key, value);
  };
  return {
    get(key) {
      if (!map.has(key)) return undefined;
      const value = map.get(key);
      touch(key, value);
      return value;
    },
    set(key, value) {
      touch(key, value);
      while (map.size > capacity) map.delete(map.keys().next().value);
      return this;
    },
    has: (key) => map.has(key),
    keys: () => [...map.keys()],
    get size() {
      return map.size;
    },
  };
}

fund-js/09-maps-sets-and-json/01-lru-cac.explanation:
Delete-then-set moves a key to the end of the Map; the first key from `map.keys()` is then always the oldest:

```js
set(key, value) {
  map.delete(key);
  map.set(key, value);
  while (map.size > capacity) map.delete(map.keys().next().value);
  return this;
}
```

`get` must refresh recency too (delete and re-set), while `has` must not. A plain object would fail the non-string-key test, because `1` and `'1'` would collide.
